def is_prime(n):
    """Return True if n is a prime number, otherwise False""" 
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def largest_prime_factor(n):
    """Return the largest prime factor of n.""" 
    largest_factor = -1
    # Check for possible even factors
    while n % 2 == 0:
        largest_factor = 2
        n = n // 2
    # Check for possible odd factors
    for i in range(3, int(n**0.5) + 1, 2): 
        while n % i == 0: 
            largest_factor = i
            n = n // i
    # If n becomes a prime number greater than 2
    if n > 2:
        largest_factor = n
    return largest_factor

# Find the largest prime factor of 9879
